'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Alert, AlertDescription } from '@/components/ui/alert';

interface BrowserControlProps {
  onStatusChange: (status: {
    isRunning: boolean;
    deviceName?: string;
    startedAt?: string;
  }) => void;
}

export default function BrowserControl({ onStatusChange }: BrowserControlProps) {
  const [url, setUrl] = useState('');
  const [referer, setReferer] = useState('');
  const [proxy, setProxy] = useState('sg.922s5.net:6300:30356354yT-zone-custom-region-JP-sessid-KFKFOZZc:OgUvBWs3');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  const handleStart = async () => {
    // 验证输入
    if (!url.trim() || !referer.trim()) {
      setMessage({ type: 'error', text: '请填写目标网址和来源' });
      return;
    }

    // 验证 URL 格式
    try {
      new URL(url);
    } catch {
      setMessage({ type: 'error', text: '无效的 URL 格式' });
      return;
    }

    setLoading(true);
    setMessage(null);

    try {
      const response = await fetch('/api/browser/start', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          url: url.trim(),
          referer: referer.trim(),
          proxy: proxy.trim() || undefined,
          languageRotation: ['ja', 'ja-JP'],
        }),
      });

      const data = await response.json();

      if (response.ok) {
        setMessage({ type: 'success', text: data.message || '浏览器启动请求已提交' });
        // 更新状态
        setTimeout(() => {
          fetch('/api/browser/status')
            .then((res) => res.json())
            .then((status) => onStatusChange(status))
            .catch(console.error);
        }, 1000);
      } else {
        setMessage({ type: 'error', text: data.error || '启动失败' });
      }
    } catch (error) {
      setMessage({ type: 'error', text: '网络错误，请稍后重试' });
    } finally {
      setLoading(false);
    }
  };

  const handleStop = async () => {
    setLoading(true);
    setMessage(null);

    try {
      const response = await fetch('/api/browser/stop', {
        method: 'POST',
      });

      const data = await response.json();

      if (response.ok) {
        setMessage({ type: 'success', text: data.message || '浏览器已关闭' });
        onStatusChange({ isRunning: false });
      } else {
        setMessage({ type: 'error', text: data.error || '关闭失败' });
      }
    } catch (error) {
      setMessage({ type: 'error', text: '网络错误，请稍后重试' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>浏览器控制</CardTitle>
        <CardDescription>配置目标网址和来源，启动模拟浏览器</CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* 目标网址 */}
        <div className="space-y-2">
          <label htmlFor="url" className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
            目标网址 <span className="text-destructive">*</span>
          </label>
          <Input
            id="url"
            type="url"
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            placeholder="https://example.com"
            disabled={loading}
          />
        </div>

        {/* 来源 (Referer) */}
        <div className="space-y-2">
          <label htmlFor="referer" className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
            来源 (Referer) <span className="text-destructive">*</span>
          </label>
          <Input
            id="referer"
            type="url"
            value={referer}
            onChange={(e) => setReferer(e.target.value)}
            placeholder="https://referer.example.com"
            disabled={loading}
          />
        </div>

        {/* 代理配置 */}
        <div className="space-y-2">
          <label htmlFor="proxy" className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
            代理配置（可选）
          </label>
          <Input
            id="proxy"
            type="text"
            value={proxy}
            onChange={(e) => setProxy(e.target.value)}
            placeholder="host:port:username:password"
            disabled={loading}
          />
          <p className="text-sm text-muted-foreground">
            格式: host:port 或 host:port:username:password
          </p>
        </div>

        {/* 消息提示 */}
        {message && (
          <Alert variant={message.type === 'success' ? 'default' : 'destructive'}>
            <AlertDescription>{message.text}</AlertDescription>
          </Alert>
        )}

        {/* 操作按钮 */}
        <div className="flex gap-3">
          <Button
            onClick={handleStart}
            disabled={loading}
            className="flex-1"
            size="lg"
          >
            {loading ? '处理中...' : '开始'}
          </Button>
          <Button
            onClick={handleStop}
            disabled={loading}
            variant="destructive"
            className="flex-1"
            size="lg"
          >
            停止
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

