'use client';

import { useState, useEffect } from 'react';
import BrowserControl from './components/BrowserControl';
import BrowserStatus from './components/BrowserStatus';

export default function Home() {
  const [status, setStatus] = useState<{
    isRunning: boolean;
    deviceName?: string;
    startedAt?: string;
  }>({ isRunning: false });

  // 轮询获取浏览器状态
  useEffect(() => {
    const fetchStatus = async () => {
      try {
        const response = await fetch('/api/browser/status');
        const data = await response.json();
        setStatus(data);
      } catch (error) {
        console.error('获取状态失败:', error);
      }
    };

    // 立即获取一次
    fetchStatus();

    // 每 2 秒轮询一次
    const interval = setInterval(fetchStatus, 2000);

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="min-h-screen bg-background py-8">
      <div className="max-w-4xl mx-auto px-4">
        <div className="mb-8">
          <h1 className="text-3xl font-bold tracking-tight">
            移动设备浏览器模拟器
          </h1>
          <p className="text-muted-foreground mt-2">
            使用 Playwright 模拟真实移动设备浏览器环境
          </p>
        </div>

        <div className="space-y-6">
          {/* 浏览器状态 */}
          <BrowserStatus status={status} />

          {/* 浏览器控制 */}
          <BrowserControl onStatusChange={setStatus} />
        </div>
      </div>
    </div>
  );
}

